package com.bank.transfer.service;

import com.bank.transfer.exception.AccountFrozenException;
import com.bank.transfer.model.Account;
import jakarta.persistence.EntityManager;
import jakarta.persistence.PersistenceContext;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;

@Service
@Slf4j
public class TransferService {

    @PersistenceContext
    private EntityManager em;

    @Transactional
    public void transfer(String fromId, String toId, BigDecimal amount) {
        Account rajesh = em.find(Account.class, fromId);
        Account priya = em.find(Account.class, toId);

        rajesh.debit(amount);
        em.flush();  // UPDATE sender balance runs NOW — but NOT committed
        log.info("Debited {} from {}; flushed (uncommitted)", amount, fromId);

        // Fraud check via query → auto-flush already made the debit visible in-TX
        BigDecimal current = em.createQuery(
                "select a.balance from Account a where a.id = :id", BigDecimal.class)
                .setParameter("id", fromId)
                .getSingleResult();
        log.info("In-transaction balance for {} seen as {}", fromId, current);

        if (priya.isFrozen()) {
            // Throwing a runtime exception → Spring ROLLS BACK
            // the flushed debit is UNDONE by the database
            throw new AccountFrozenException(toId);
        }
        priya.credit(amount);  // never reached in the frozen case
    }
}
